import { criteria, samples } from './criteria.js';
import { analyzeReport, buildSignalMap } from './analyzer.js';

const $ = (s, root = document) => root.querySelector(s);
const app = $('#app');
let sampleId = new URLSearchParams(location.search).get('sample');
if (!samples[sampleId]) sampleId = 'mixed';
let values = { ...samples[sampleId].values };
let analysis = analyzeReport(values);
let activeView = location.pathname === '/demo' ? 'demo' : 'home';
let filter = 'all';
let selectedRule = null;
let previous = null;
let toastTimer;
let reportOpen = false;
let reportTab = 'overview';
let tourStep = null;
let tourSeenThisPage = false;

const statusLabel = { within: 'Within range', below: 'Below range', above: 'Above range', invalid: 'Needs attention', unsupported: 'Unsupported' };
function showToast(message) { const el = $('#toast'); if (!el) return; el.textContent = message; el.classList.add('visible'); clearTimeout(toastTimer); toastTimer = setTimeout(() => el.classList.remove('visible'), 2800); }
function setView(view) { activeView = view; window.history.pushState({ view }, '', view === 'demo' ? '/demo' : '/'); window.scrollTo(0, 0); render(); if (view === 'demo') maybeStartTour(); }
window.addEventListener('popstate', () => { activeView = location.pathname === '/demo' ? 'demo' : 'home'; render(); });

function header() { return `<header class="topbar"><a class="brand" href="/" data-view="home"><span class="brand-mark">O</span><span>MediOTO<span class="brand-ai">AI</span></span></a><nav><button class="nav-link ${activeView === 'home' ? 'active' : ''}" data-view="home">Overview</button><button class="nav-link ${activeView === 'demo' ? 'active' : ''}" data-view="demo">Analyze report</button><a class="nav-link" href="#how-it-works" data-scroll="how-it-works">How it works</a></nav><div class="top-actions">${activeView === 'demo' ? '<button class="tour-launch" data-action="start-tour">? Guided tour</button>' : ''}<span class="demo-pill"><i></i> Demo environment</span><button class="avatar" aria-label="Alshi Coders team">A</button></div><button class="menu-toggle" aria-label="Open navigation">☰</button></header>`; }

function footer() { return `<footer class="footer"><span>© 2026 MediOTO AI · Alshi Coders</span><span>Educational prototype · Fictional data only</span><button data-modal="safety">Safety & privacy</button></footer>`; }

function landing() { return `<main><section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="eyebrow-dot"></span> EXPLAINABLE LAB REPORT ANALYSIS</div><h1>Medical reports contain numbers.<br><em>Understand what stands out.</em></h1><p class="hero-description">MediOTO AI identifies measurements outside configured intervals, explains each flag, and connects predefined patterns so you can prepare informed questions for a healthcare professional.</p><div class="hero-actions"><a class="button primary" href="/demo" data-view="demo">Try interactive demo <span>→</span></a><a class="button secondary" href="#how-it-works" data-scroll="how-it-works">Explore how it works</a></div><div class="hero-meta"><span class="avatar-stack"><i>✓</i></span><span>Deterministic analysis</span><b>·</b><span>No account or API key</span></div></div><div class="hero-art" aria-label="Illustration of an analyzed fictional laboratory report"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="report-card" data-discovery tabindex="0" role="button" aria-pressed="false" aria-label="Reveal a thoughtful note"><div class="report-top"><span class="mini-logo">O</span><span>LAB REPORT <small>DEMO-2087</small></span><span class="report-dot"></span></div><div class="report-greeting">A clearer view of your results</div><div class="report-small">FICTIONAL SAMPLE · ANALYSIS COMPLETE</div><div class="report-metric"><span>Hemoglobin</span><b>11.2 <small>g/dL</small></b><span class="state-tag low">Below range</span></div><div class="report-metric"><span>Platelets</span><b>438 <small>×10⁹/L</small></b><span class="state-tag high">Above range</span></div><div class="report-metric"><span>Fasting glucose</span><b>108 <small>mg/dL</small></b><span class="state-tag high">Above range</span></div><div class="report-foot"><span class="mini-check">✓</span><span>Every flag has an explanation</span><span>↗</span></div></div><div class="float-note note-top"><span class="note-icon">◎</span><span><b>SignalScan</b><small>Clear rule-based checks</small></span></div><div class="float-note note-bottom"><span class="note-icon teal-icon">⌘</span><span><b>SignalMap</b><small>Connected by configured rules</small></span></div><div class="art-cross">✳</div></div><div class="hero-bottom"><span><b>01</b> Configure criteria</span><span><b>02</b> Explain each flag</span><span><b>03</b> Prepare questions</span><span class="hero-scroll">SCROLL TO EXPLORE ↓</span></div></section><section class="trust-strip"><div><span class="strip-icon">⌁</span><span><b>Clarity before complexity</b><small>Designed for understandable results</small></span></div><div><span class="strip-icon blue">◇</span><span><b>Transparent by design</b><small>See the rule behind every flag</small></span></div><div><span class="strip-icon amber">⌖</span><span><b>Professional review</b><small>Questions, not diagnoses</small></span></div><div><span class="strip-icon">◉</span><span><b>Privacy-respectful demo</b><small>Runs locally in your browser</small></span></div></section><section id="how-it-works" class="how-section"><div class="section-heading"><div class="eyebrow">A SIMPLE, EXPLAINABLE WORKFLOW</div><h2>From a page of results to a<br>clearer conversation.</h2><p>Every step uses visible rules and fictional sample values. Nothing is hidden behind a black box.</p></div><div class="steps"><article><span class="step-number">01</span><div class="step-icon">▤</div><h3>Choose a report</h3><p>Load one of three fictional reports or enter measurements manually.</p></article><article><span class="step-number">02</span><div class="step-icon">⌕</div><h3>Scan the signals</h3><p>SignalScan compares values to the selected illustrative criteria.</p></article><article><span class="step-number">03</span><div class="step-icon">⌘</div><h3>See the connections</h3><p>SignalMap only connects findings when a documented rule triggers.</p></article><article><span class="step-number">04</span><div class="step-icon">↗</div><h3>Prepare to discuss</h3><p>Review plain-language explanations and print a summary for discussion.</p></article></div></section><section class="cta-band"><div><span class="eyebrow">YOUR FIRST LOOK TAKES LESS THAN TWO MINUTES</span><h2>Try the analysis with fictional data.</h2><p>Choose a sample, inspect its results, and change a value in the What-If Lab.</p></div><a class="button white-button" href="/demo" data-view="demo">Open interactive demo <span>→</span></a></section><section class="safety-band"><span class="safety-icon">ⓘ</span><div><b>An educational prototype, not a diagnostic tool.</b><p>Ranges shown here are illustrative demo values. Laboratory results require interpretation by a qualified healthcare professional in clinical context.</p></div><button data-modal="safety">Read our safety notes ↗</button></section></main>${footer()}`; }

function resultRow(r) { return `<tr class="result-row"><td><b>${r.name}</b><small>${r.id.replaceAll('_', ' ').toUpperCase()}</small></td><td class="numeric">${r.value ?? '—'} <span>${r.unit || ''}</span></td><td class="numeric">${r.interval ? `${r.interval[0]} – ${r.interval[1]}` : '—'} <span>${r.expectedUnit || ''}</span></td><td><span class="status status-${r.status}"><i></i>${statusLabel[r.status] || r.status}</span></td><td><button class="icon-button explain-btn" data-explain="${r.id}" aria-label="Explain ${r.name}">↗</button></td></tr>`; }
function resultCard(r) { return `<article class="mobile-result"><div><b>${r.name}</b><span class="status status-${r.status}"><i></i>${statusLabel[r.status] || r.status}</span></div><p class="numeric">${r.value ?? '—'} <span>${r.unit || ''}</span><small>Reference: ${r.interval ? `${r.interval[0]}–${r.interval[1]} ${r.expectedUnit}` : 'Unavailable'}</small></p><button class="text-link" data-explain="${r.id}">Why this result? ↗</button></article>`; }

function mapMarkup() { const map = buildSignalMap(analysis); const pos = { glucose: [27, 42], hba1c: [73, 42] }; const glucose = map.nodes.find(n => n.id === 'glucose'), hba1c = map.nodes.find(n => n.id === 'hba1c');
  if (!map.links.length) return `<div class="map-empty"><div class="empty-graphic"><span>◉</span><i>⌁</i><span>◉</span></div><b>No configured combination rule triggered</b><p>SignalMap creates connections only when an explicit rule matches this sample. Individual measurements remain available above.</p></div>`;
  return `<div class="signal-map"><svg viewBox="0 0 600 250" role="img" aria-label="Connection between fasting glucose and HbA1c under the configured review rule"><line class="map-line" x1="162" y1="105" x2="438" y2="105"/><g class="map-node" data-node="glucose" tabindex="0" role="button" aria-label="Fasting blood glucose ${glucose?.value} mg per dL"><circle class="node-halo" cx="162" cy="105" r="48"/><circle class="node-core ${glucose?.status}" cx="162" cy="105" r="34"/><text x="162" y="101" text-anchor="middle">${glucose?.value}</text><text class="node-unit" x="162" y="119" text-anchor="middle">mg/dL</text><text class="node-label" x="162" y="180" text-anchor="middle">Fasting glucose</text></g><g class="map-node" data-node="hba1c" tabindex="0" role="button" aria-label="HbA1c ${hba1c?.value} percent"><circle class="node-halo" cx="438" cy="105" r="48"/><circle class="node-core ${hba1c?.status}" cx="438" cy="105" r="34"/><text x="438" y="101" text-anchor="middle">${hba1c?.value}</text><text class="node-unit" x="438" y="119" text-anchor="middle">%</text><text class="node-label" x="438" y="180" text-anchor="middle">HbA1c</text></g><g class="map-link-hit" data-rule="glucose_pair_review" tabindex="0" role="button" aria-label="Open related glucose measurements rule"><rect x="242" y="88" width="116" height="35" rx="17"/><text x="300" y="109" text-anchor="middle">RULE TRIGGERED ↗</text></g></svg><button class="map-rule-card" data-rule="glucose_pair_review"><span class="rule-indicator">↔</span><span><b>Related glucose measurements</b><small>Both values meet the configured review criteria</small></span><span class="rule-arrow">↗</span></button></div>`;
}

function demo() { const counts = analysis.counts; const shown = analysis.results.filter(r => filter === 'all' || r.status === filter); const sample = samples[sampleId]; return `<main class="demo-page"><div class="demo-heading"><div><div class="eyebrow">SIGNALSCAN · DEMONSTRATION WORKSPACE</div><h1>Analyze a report</h1><p>Explore how MediOTO AI evaluates fictional lab measurements.</p></div><div class="heading-actions"><button class="button secondary small" data-action="reset">↺ Reset demo</button><button class="button primary small" data-tour="print" data-action="print">⤓ Print summary</button></div></div><div class="fiction-banner"><span>ⓘ</span><span><b>Fictional-data demonstration.</b> All ranges are illustrative. This prototype does not diagnose conditions.</span><button data-modal="safety">Safety details ↗</button></div><div class="workspace-grid"><aside class="side-column"><section class="panel sample-panel" data-tour="samples"><div class="panel-title"><div><span class="eyebrow">START WITH A SAMPLE</span><h2>Choose a report</h2></div><span class="sample-symbol">▤</span></div><p>Each report is fictional and loads editable values into the analyzer.</p><div class="sample-options">${Object.entries(samples).map(([id,s])=>`<button class="sample-option ${sampleId===id?'selected':''}" data-sample="${id}"><span class="sample-select">${sampleId===id?'✓':''}</span><span><b>${s.title}</b><small>${Object.keys(s.values).length} measurements · ${s.id}</small></span><span class="sample-arrow">→</span></button>`).join('')}</div><details class="entry-editor"><summary>Edit or remove measurements</summary><label class="field-label" for="entry-select">Measurement</label><select id="entry-select">${Object.entries(criteria).map(([id,c])=>`<option value="${id}">${c.name}</option>`).join('')}</select><div class="entry-controls"><input id="entry-value" type="number" step="any" aria-label="Measurement value"><span id="entry-unit">${criteria.glucose.unit}</span><button data-action="save-entry">Save</button></div><div class="entry-list">${Object.keys(values).map(id=>`<div><span>${criteria[id]?.name || id}</span><b>${values[id]} ${criteria[id]?.unit || ''}</b><button data-remove="${id}" aria-label="Remove ${criteria[id]?.name || id}">×</button></div>`).join('')}</div></details><button class="button primary full" data-tour="analyze" data-action="analyze">Analyze report <span>→</span></button><button class="text-link manual-link" data-action="add">＋ Add measurement</button></section><section class="panel summary-panel"><div class="panel-title"><div><span class="eyebrow">COMPUTED SUMMARY</span><h2>Analysis snapshot</h2></div><span class="live-indicator"><i></i> LIVE</span></div><div class="summary-grid"><div><b>${counts.total}</b><small>Analyzed</small></div><div><b>${counts.within}</b><small>Within range</small></div><div><b class="amber-text">${counts.below}</b><small>Below range</small></div><div><b class="red-text">${counts.above}</b><small>Above range</small></div></div><div class="summary-foot">${counts.combinations ? `<span class="flag-icon">!</span><b>${counts.combinations} combination review flag</b>` : `<span class="ok-icon">✓</span><b>No combination review flags</b>`}</div></section><section class="panel whatif-panel"><div class="panel-title"><div><span class="eyebrow">SANDBOX</span><h2>What-If Lab</h2></div><span class="whatif-icon">⌁</span></div><p>Adjust a fictional value and see how the same analyzer responds.</p><label for="whatif-select" class="field-label">Measurement</label><select id="whatif-select">${Object.entries(criteria).map(([id,c])=>`<option value="${id}">${c.name}</option>`).join('')}</select><div class="whatif-input"><input id="whatif-value" type="number" step="any" value="${values.glucose ?? 108}" aria-label="Simulation value"><span id="whatif-unit">${criteria.glucose.unit}</span><button data-action="apply-whatif">Apply</button></div><p class="whatif-note">Changes update the real analyzer and SignalMap.</p></section></aside><div class="main-column"><section class="panel results-panel" data-tour="results"><div class="results-head"><div><span class="eyebrow">SIGNALSCAN RESULTS</span><h2>${sample.title}</h2><p>Report ${sample.id} <span>·</span> ${Object.keys(values).length} entered measurements</p></div><button class="icon-button export-btn" data-action="print" aria-label="Print report">⤓</button></div><div class="filter-row"><span>MEASUREMENTS</span><div class="filter-buttons">${[['all','All'],['below','Below'],['above','Above'],['within','Within']].map(([key,label])=>`<button class="filter-button ${filter===key?'active':''}" data-filter="${key}">${label}${key==='all'?` <b>${analysis.results.length}</b>`:''}</button>`).join('')}</div></div><div class="table-wrap"><table><thead><tr><th>MEASUREMENT</th><th>VALUE</th><th>ILLUSTRATIVE INTERVAL</th><th>STATUS</th><th></th></tr></thead><tbody>${shown.map(resultRow).join('') || `<tr><td colspan="5" class="no-results">No measurements match this filter.</td></tr>`}</tbody></table></div><div class="mobile-results">${shown.map(resultCard).join('') || '<p class="no-results">No measurements match this filter.</p>'}</div><div class="table-foot"><span>↗</span> Illustrative intervals are for this demo only. Actual lab ranges vary by lab and context.</div></section><section class="panel map-panel" data-tour="signalmap"><div class="map-head"><div><span class="eyebrow">SIGNALMAP</span><h2>Connected findings</h2><p>Connections appear only when a configured rule triggers.</p></div><span class="map-legend"><i></i> Review rule</span></div>${mapMarkup()}</section><section class="panel review-panel"><div class="review-icon">✳</div><div><span class="eyebrow">PROFESSIONAL REVIEW</span><h3>Questions to consider discussing</h3><p>${counts.combinations ? 'Could we review the glucose measurements together with fasting status, age, and clinical context? Are repeat or confirmatory tests appropriate for this situation?' : 'How should these results be interpreted alongside my history and the reference intervals from the testing laboratory?'} </p><small>These are neutral discussion prompts, not medical recommendations.</small></div></section><section class="panel whatif-detail" data-tour="whatif"><div class="whatif-heading"><div><span class="eyebrow">INTERACTIVE SIMULATION</span><h2>What-If Lab</h2><p>Change a value to recalculate statuses and connected findings.</p></div><span class="simulation-tag">FICTIONAL DATA ONLY</span></div>${previous ? `<div class="change-summary"><b>Simulation update</b><span>${previous.name}: ${previous.value} → ${values[previous.id]} ${criteria[previous.id].unit}</span><span class="status status-${analysis.results.find(x=>x.id===previous.id)?.status}"><i></i>${statusLabel[analysis.results.find(x=>x.id===previous.id)?.status]}</span><button data-action="restore-value">Undo</button></div>` : ''}<div class="slider-list">${['glucose','hba1c','hemoglobin','platelets'].map(id=>`<label class="slider-row"><span>${criteria[id].name}<small>${criteria[id].low}–${criteria[id].high} ${criteria[id].unit}</small></span><input type="range" min="${Math.max(0,criteria[id].low*.5)}" max="${criteria[id].high*1.5}" step="${id==='hba1c'?'0.1':id==='hemoglobin'?'0.1':'1'}" value="${values[id] ?? criteria[id].low}" data-slider="${id}"><b class="numeric">${values[id] ?? '—'} <small>${criteria[id].unit}</small></b></label>`).join('')}</div><div class="whatif-disclaimer">ⓘ Fictional-data simulation. Changes demonstrate software behavior and do not predict individual health outcomes.</div></section></div></div></main>${footer()}<div class="toast" id="toast" role="status" aria-live="polite"></div><div id="modal-root"></div>`; }

function render() { app.innerHTML = `${header()}${activeView === 'demo' ? demo() : landing()}${activeView === 'home' ? '<div class="toast" id="toast" role="status" aria-live="polite"></div><div id="modal-root"></div>' : ''}`; if (activeView === 'demo' && reportOpen) $('#modal-root').innerHTML = reportMarkup(); bind(); bindModalActions(); paintTour(); }

function explanation(id) { const r = analysis.results.find(x => x.id === id); if (!r) return; reportOpen = false; const related = analysis.rules.filter(rule => rule.triggered && rule.measurements.includes(id)); const content = `<div class="modal-backdrop" data-close="true"><section class="explain-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="modal-close" data-close="true" aria-label="Close">×</button><span class="eyebrow">WHY THIS ${r.status==='within'?'RESULT':'FLAG'}?</span><h2 id="modal-title">${r.name}</h2><div class="modal-value"><b>${r.value ?? '—'}</b><span>${r.unit}</span><span class="status status-${r.status}"><i></i>${statusLabel[r.status] || r.status}</span></div><dl class="explain-list"><div><dt>Configured interval</dt><dd>${r.interval ? `${r.interval[0]}–${r.interval[1]} ${r.expectedUnit}` : 'Not available'}</dd></div><div><dt>How it was evaluated</dt><dd>${r.reason}</dd></div><div><dt>Provenance</dt><dd>${r.source || 'No configured criterion'}. All values shown are illustrative demo criteria.</dd></div>${r.context?.length?`<div><dt>Context not supplied</dt><dd>${r.context.join(', ')} can affect clinical interpretation and are not accounted for by this prototype.</dd></div>`:''}${related.length?`<div><dt>Related configured rule</dt><dd>${related.map(x=>x.name).join(', ')}. ${related[0].explanation}</dd></div>`:''}<div><dt>Limitation</dt><dd>Numerical comparison alone does not establish a diagnosis or explain the cause. A qualified healthcare professional can interpret results in context.</dd></div></dl></section></div>`; $('#modal-root').innerHTML = content; $('#modal-root .modal-close')?.focus(); }

function ruleExplanation(id) { const rule = analysis.rules.find(r => r.id === id); if (!rule) return; $('#modal-root').innerHTML = `<div class="modal-backdrop" data-close="true"><section class="explain-modal rule-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="modal-close" data-close="true" aria-label="Close">×</button><span class="eyebrow">CONFIGURED COMBINATION RULE</span><h2 id="modal-title">${rule.name}</h2><div class="rule-triggered">${rule.triggered?'✓ Rule triggered':'○ Rule not triggered'}</div><p class="rule-description">${rule.explanation}</p><h3>Exact conditions</h3><ul>${rule.conditions.map(c=>`<li>${c}</li>`).join('')}</ul><p class="rule-limit"><b>Context needed:</b> ${rule.requiredContext.join(', ')}. ${rule.limitation}</p></section></div>`; }

function rangeChartRow(r) {
  const span = Math.max(r.interval[1] - r.interval[0], 1);
  const min = Math.max(0, r.interval[0] - span * .65), max = r.interval[1] + span * .65;
  const range = max - min;
  const left = ((r.interval[0] - min) / range) * 100;
  const width = ((r.interval[1] - r.interval[0]) / range) * 100;
  const marker = Math.max(0, Math.min(100, ((r.value - min) / range) * 100));
  return `<button class="range-row" data-report-explain="${r.id}" aria-label="Explain ${r.name}: ${r.value} ${r.unit}, ${statusLabel[r.status]}"><span class="range-name">${r.name}<small>${r.value} ${r.unit} · ${statusLabel[r.status]}</small></span><span class="range-track"><i class="range-normal" style="left:${left}%;width:${width}%"></i><i class="range-marker ${r.status}" style="left:${marker}%"></i></span><span class="range-ends"><small>${min.toFixed(1)}</small><small>${max.toFixed(1)} ${r.unit}</small></span></button>`;
}

function reportMarkup() {
  const c = analysis.counts, total = Math.max(c.total + c.issues, 1);
  const p1 = c.within / total * 100, p2 = (c.within + c.below) / total * 100, p3 = (c.within + c.below + c.above) / total * 100;
  const rows = analysis.results.filter(r => r.interval);
  return `<div class="modal-backdrop report-backdrop" data-close="true"><section class="report-modal" role="dialog" aria-modal="true" aria-labelledby="report-title"><div class="report-modal-head"><div><span class="eyebrow">SIGNALSCAN · COMPUTED REPORT</span><h2 id="report-title">${samples[sampleId].title}</h2><p>${samples[sampleId].id} <span>·</span> Fictional data <span>·</span> ${c.total} measurements analyzed</p></div><button class="modal-close" data-close="true" aria-label="Close report">×</button></div><div class="report-tabs" role="tablist"><button class="report-tab ${reportTab==='overview'?'selected':''}" data-report-tab="overview" role="tab" aria-selected="${reportTab==='overview'}">Overview</button><button class="report-tab ${reportTab==='ranges'?'selected':''}" data-report-tab="ranges" role="tab" aria-selected="${reportTab==='ranges'}">Reference graphs <span>${rows.length}</span></button></div><div class="report-modal-body">${reportTab==='overview'?`<div class="report-overview-grid"><section class="report-chart-card" data-tour="report"><div class="report-section-title"><div><h3>Result distribution</h3><p>Computed from this report's entries</p></div><span class="live-indicator"><i></i> CURRENT</span></div><div class="distribution-layout"><div class="donut-chart" role="img" aria-label="${c.within} within, ${c.below} below, ${c.above} above, ${c.issues} issues" style="background:conic-gradient(#378e75 0 ${p1}%,#c58b2a ${p1}% ${p2}%,#bb5b58 ${p2}% ${p3}%,#aab4b9 ${p3}% 100%)"><div><b>${c.total}</b><small>analyzed</small></div></div><div class="distribution-legend"><button data-report-filter="within"><i class="legend-green"></i><span>Within range</span><b>${c.within}</b></button><button data-report-filter="below"><i class="legend-amber"></i><span>Below range</span><b>${c.below}</b></button><button data-report-filter="above"><i class="legend-red"></i><span>Above range</span><b>${c.above}</b></button>${c.issues?`<button data-report-filter="invalid"><i class="legend-gray"></i><span>Input issues</span><b>${c.issues}</b></button>`:''}</div></div><p class="chart-help">Select a category to filter measurements on the report page.</p></section><section class="report-chart-card report-flag-card"><div class="report-section-title"><div><h3>Combination review</h3><p>Only configured rules can create a connection</p></div><span class="rule-indicator">↔</span></div>${analysis.rules.filter(r=>r.triggered).length?analysis.rules.filter(r=>r.triggered).map(r=>`<button class="report-rule-link" data-report-map><b>${r.name}</b><span>${r.measurements.map(id=>`${criteria[id].name}: ${analysis.results.find(x=>x.id===id)?.value} ${criteria[id].unit}`).join(' · ')}</span><small>Open SignalMap details →</small></button>`).join(''):`<div class="report-no-flags"><span>✓</span><b>No combination rules triggered</b><p>Individual results can still be outside their intervals. No configured relationship matched this report.</p></div>`}</section></div><section class="report-chart-card report-measurements"><div class="report-section-title"><div><h3>Measurements at a glance</h3><p>Choose a result to inspect its exact comparison and limitations</p></div><button class="text-link" data-report-tab="ranges">View graphs →</button></div><div class="report-quick-list">${analysis.results.map(r=>`<button class="quick-result" data-report-explain="${r.id}"><span>${r.name}</span><b>${r.value ?? '—'} ${r.unit}</b><span class="status status-${r.status}"><i></i>${statusLabel[r.status]||r.status}</span><span>↗</span></button>`).join('')}</div></section>`:`<section class="report-chart-card reference-chart"><div class="report-section-title"><div><h3>Values against illustrative intervals</h3><p>Markers show the entered value; shaded segment is the configured interval. Select a graph for its explanation.</p></div><span class="simulation-tag">DEMO RANGES</span></div><div class="range-axis"><span>BELOW INTERVAL</span><span>CONFIGURED INTERVAL</span><span>ABOVE INTERVAL</span></div><div class="range-list">${rows.map(rangeChartRow).join('')}</div><p class="range-disclaimer">These graphs use illustrative demo criteria. Real laboratory ranges vary by lab and clinical context.</p></section>`}</div><div class="report-modal-foot"><span>ⓘ Educational prototype · Not a diagnosis</span><button class="button secondary small" data-report-map>Open SignalMap</button><button class="button secondary small" data-action="print">Print summary</button><button class="button primary small" data-report-close>Continue to report <span>→</span></button></div></section></div>`;
}

const tourSteps = [
  { target: '[data-tour="samples"]', title: '1. Choose a fictional report', text: 'Start with one of three sample reports. Each one demonstrates different analyzer behavior. Try the combined-indicator example to see a configured relationship.', next: 'Next' },
  { target: '[data-tour="analyze"]', title: '2. Run SignalScan', text: 'This runs the deterministic analyzer against the values currently loaded. It checks units, illustrative intervals, and the configured combination rule.', next: 'Analyze & open report' },
  { target: '[data-tour="report"]', title: '3. Read the interactive report', text: 'This distribution chart is computed from the actual results. Select a category to filter the report, or switch tabs to inspect the value-versus-interval graphs.', next: 'Continue tour' },
  { target: '[data-tour="results"]', title: '4. Inspect every measurement', text: 'The table and filters show the exact computed status for each measurement. Open any row to see why it was flagged and what context is missing.', next: 'Next' },
  { target: '[data-tour="results"]', title: '5. Open “Why this flag?”', text: 'Use the arrow on a result row (or “Why this result?” on mobile) to see the entered value, criterion, comparison, provenance, and limitations.', next: 'Next' },
  { target: '[data-tour="signalmap"]', title: '6. Explore SignalMap', text: 'Connections are created only by configured rules. Click the connection or a node to inspect the rule and its exact conditions.', next: 'Next' },
  { target: '[data-tour="whatif"]', title: '7. Try the What-If Lab', text: 'Move a slider or edit a value to rerun the same engine. Watch statuses and SignalMap update from the new fictional input.', next: 'Next' },
  { target: '[data-tour="print"]', title: '8. Print or export the summary', text: 'The print action opens a report-ready browser print view with the current computed measurements, combination rules, and safety note.', next: 'Finish tour' }
];

function maybeStartTour() {
  if (tourStep !== null || tourSeenThisPage) return;
  try { if (sessionStorage.getItem('medioto-tour-seen')) return; } catch {}
  tourSeenThisPage = true;
  try { sessionStorage.setItem('medioto-tour-seen', '1'); } catch {}
  tourStep = 0;
  render();
}

function paintTour() {
  app.querySelectorAll('.tour-focus').forEach(el => el.classList.remove('tour-focus'));
  app.querySelector('#tour-layer')?.remove();
  if (tourStep === null || activeView !== 'demo') return;
  const step = tourSteps[tourStep];
  const target = app.querySelector(step.target);
  target?.classList.add('tour-focus');
  if (target && tourStep !== 0 && tourStep !== 1 && tourStep !== 7) target.scrollIntoView({ behavior: 'smooth', block: 'center' });
  app.insertAdjacentHTML('beforeend', `<div class="tour-shade" aria-hidden="true"></div><section class="tour-card" id="tour-layer" role="dialog" aria-labelledby="tour-title" aria-describedby="tour-copy"><div class="tour-card-top"><span>MEDIOTO QUICK START</span><button data-tour-skip aria-label="Skip guided tour">Skip ×</button></div><div class="tour-progress"><i style="width:${((tourStep+1)/tourSteps.length)*100}%"></i></div><small class="tour-counter">STEP ${tourStep+1} OF ${tourSteps.length}</small><h2 id="tour-title">${step.title}</h2><p id="tour-copy">${step.text}</p><div class="tour-actions"><button class="text-link" data-tour-back ${tourStep===0?'disabled':''}>← Back</button><button class="button primary small" data-tour-next>${step.next} <span>→</span></button></div></section>`);
}

function finishTour() { tourStep = null; render(); }
function nextTour() {
  if (tourStep === 1) { analysis = analyzeReport(values); reportOpen = true; reportTab = 'overview'; tourStep = 2; render(); return; }
  if (tourStep === 2) { reportOpen = false; tourStep = 3; render(); return; }
  if (tourStep >= tourSteps.length - 1) { finishTour(); return; }
  tourStep++;
  render();
}

function bindModalActions() {
  app.onclick = event => {
    if (event.target.closest('[data-tour-next]')) { nextTour(); return; }
    if (event.target.closest('[data-tour-back]')) { if (tourStep === 2) { reportOpen = false; tourStep = 1; } else if (tourStep > 0) tourStep--; render(); return; }
    if (event.target.closest('[data-tour-skip]')) { finishTour(); return; }
    const closeButton = event.target.closest('.modal-close, [data-report-close]');
    const backdrop = event.target.closest('.modal-backdrop');
    if (closeButton || (backdrop && event.target === backdrop)) {
      reportOpen = false;
      $('#modal-root')?.replaceChildren();
      if (tourStep === 2) tourStep = 3;
      render();
      return;
    }
  };
  document.onkeydown = event => {
    if (event.key === 'Escape') {
      if ($('#modal-root')?.childElementCount) { reportOpen = false; $('#modal-root').replaceChildren(); if (tourStep === 2) tourStep = 3; render(); }
      else if (tourStep !== null) finishTour();
    }
  };
}

function bind() { document.querySelectorAll('[data-view]').forEach(el => el.addEventListener('click', e=>{e.preventDefault();setView(el.dataset.view);})); document.querySelectorAll('[data-scroll]').forEach(el=>el.addEventListener('click',e=>{if(activeView==='home'){e.preventDefault();document.getElementById(el.dataset.scroll)?.scrollIntoView({behavior:'smooth'});}}));
  document.querySelectorAll('[data-sample]').forEach(el=>el.addEventListener('click',()=>{sampleId=el.dataset.sample;values={...samples[sampleId].values};analysis=analyzeReport(values);previous=null;render();}));
  document.querySelectorAll('[data-filter]').forEach(el=>el.addEventListener('click',()=>{filter=el.dataset.filter;render();}));
  document.querySelectorAll('[data-explain]').forEach(el=>el.addEventListener('click',()=>explanation(el.dataset.explain)));
  document.querySelectorAll('[data-rule]').forEach(el=>el.addEventListener('click',()=>ruleExplanation(el.dataset.rule)));
  document.querySelectorAll('[data-node]').forEach(el=>el.addEventListener('click',()=>explanation(el.dataset.node)));
  document.querySelectorAll('[data-report-tab]').forEach(el=>el.addEventListener('click',()=>{reportTab=el.dataset.reportTab;render();}));
  document.querySelectorAll('[data-report-explain]').forEach(el=>el.addEventListener('click',()=>explanation(el.dataset.reportExplain)));
  document.querySelectorAll('[data-report-filter]').forEach(el=>el.addEventListener('click',()=>{filter=el.dataset.reportFilter;reportOpen=false;if(tourStep===2)tourStep=3;render();$('.results-panel')?.scrollIntoView({behavior:'smooth',block:'start'});}));
  document.querySelectorAll('[data-report-map]').forEach(el=>el.addEventListener('click',()=>{reportOpen=false;if(tourStep===2)tourStep=5;render();$('.map-panel')?.scrollIntoView({behavior:'smooth',block:'center'});}));
  document.querySelectorAll('[data-action="start-tour"]').forEach(el=>el.addEventListener('click',()=>{tourSeenThisPage=true;tourStep=0;reportOpen=false;render();}));
  document.querySelectorAll('[data-tour-next]').forEach(el=>el.addEventListener('click',nextTour));
  document.querySelectorAll('[data-tour-back]').forEach(el=>el.addEventListener('click',()=>{if(tourStep===2){reportOpen=false;tourStep=1;}else if(tourStep>0)tourStep--;render();}));
  document.querySelectorAll('[data-tour-skip]').forEach(el=>el.addEventListener('click',finishTour));
  document.querySelectorAll('[data-modal]').forEach(el=>el.addEventListener('click',()=>{ $('#modal-root').innerHTML=`<div class="modal-backdrop" data-close="true"><section class="explain-modal" role="dialog" aria-modal="true" aria-labelledby="safety-title"><button class="modal-close" data-close="true" aria-label="Close">×</button><span class="eyebrow">ABOUT & SAFETY</span><h2 id="safety-title">Clarity with clear limits.</h2><div class="explain-list"><div><dt>How analysis works</dt><dd>SignalScan uses deterministic comparisons against configured criteria in src/criteria.js. Inclusive interval boundaries count as within range.</dd></div><div><dt>Illustrative criteria</dt><dd>Every range in this prototype is explicitly labeled illustrative and is not a clinical standard. Interpretation depends on context that this demo does not collect.</dd></div><div><dt>What this is not</dt><dd>MediOTO AI does not diagnose, prescribe treatment, or replace a qualified healthcare professional. Combination rules prompt discussion only.</dd></div><div><dt>Privacy</dt><dd>Analysis runs locally in your browser. Sample selections are not uploaded or saved. The Reset demo button restores fictional sample data.</dd></div></div><p class="safety-modal-foot">For personal health concerns, speak with a qualified healthcare professional.</p></section></div>`; }));
  document.querySelectorAll('[data-action="print"]').forEach(el=>el.addEventListener('click',()=>window.print()));
  document.querySelectorAll('[data-action="reset"]').forEach(el=>el.addEventListener('click',()=>{sampleId='mixed';values={...samples[sampleId].values};analysis=analyzeReport(values);filter='all';previous=null;render();showToast('Demo reset to the mixed-results sample.');}));
  document.querySelectorAll('[data-action="analyze"]').forEach(el=>el.addEventListener('click',()=>{analysis=analyzeReport(values);reportOpen=true;reportTab='overview';if(tourStep===1)tourStep=2;render();$('#modal-root .modal-close')?.focus();}));
  document.querySelectorAll('[data-action="add"]').forEach(el=>el.addEventListener('click',()=>{const missing=Object.keys(criteria).find(id=>!(id in values));if(!missing){showToast('All supported measurements are already included.');return;}values[missing]=criteria[missing].low;analysis=analyzeReport(values);render();showToast(`${criteria[missing].name} added with an illustrative value.`);}));
  const entrySelect=$('#entry-select'); if(entrySelect){entrySelect.value=Object.keys(values).find(id=>id==='glucose')||Object.keys(criteria)[0];$('#entry-value').value=values[entrySelect.value]??'';$('#entry-unit').textContent=criteria[entrySelect.value].unit;entrySelect.addEventListener('change',()=>{$('#entry-value').value=values[entrySelect.value]??'';$('#entry-unit').textContent=criteria[entrySelect.value].unit;});}
  document.querySelectorAll('[data-action="save-entry"]').forEach(el=>el.addEventListener('click',()=>{const id=$('#entry-select').value,raw=$('#entry-value').value;if(raw.trim()===''){showToast('Enter a numeric value before saving.');return;}const n=Number(raw);if(!Number.isFinite(n)){showToast('Enter a finite number before saving.');return;}values[id]=n;analysis=analyzeReport(values);render();showToast(`${criteria[id].name} saved and reanalyzed.`);}));
  document.querySelectorAll('[data-remove]').forEach(el=>el.addEventListener('click',()=>{delete values[el.dataset.remove];analysis=analyzeReport(values);previous=null;render();showToast(`${criteria[el.dataset.remove].name} removed.`);}));
  const select=$('#whatif-select'); if(select){select.value='glucose';select.addEventListener('change',()=>{$('#whatif-value').value=values[select.value]??criteria[select.value].low;$('#whatif-unit').textContent=criteria[select.value].unit;});}
  document.querySelectorAll('[data-action="apply-whatif"]').forEach(el=>el.addEventListener('click',()=>applyInput()));
  document.querySelectorAll('[data-slider]').forEach(el=>el.addEventListener('change',()=>{const id=el.dataset.slider;previous={id,name:criteria[id].name,value:values[id]};values[id]=Number(el.value);analysis=analyzeReport(values);render();}));
  document.querySelectorAll('[data-action="restore-value"]').forEach(el=>el.addEventListener('click',()=>{if(previous){values[previous.id]=previous.value;analysis=analyzeReport(values);previous=null;render();}}));
  const toggle=$('.menu-toggle'); toggle?.addEventListener('click',()=>$('.topbar nav').classList.toggle('nav-open'));
  const discovery=$('[data-discovery]'); if(discovery){const reveal=()=>{const open=discovery.classList.toggle('note-revealed');discovery.setAttribute('aria-pressed',String(open));};discovery.addEventListener('click',reveal);discovery.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();reveal();}});}
}
function applyInput(){const id=$('#whatif-select').value, raw=$('#whatif-value').value; if(raw.trim()===''){showToast('Enter a number before applying the simulation.');return;}const n=Number(raw);if(!Number.isFinite(n)){showToast('Enter a finite number to continue.');return;}previous={id,name:criteria[id].name,value:values[id]};values[id]=n;analysis=analyzeReport(values);render();showToast('What-If Lab recalculated with the same analysis engine.');}

render();
if (activeView === 'demo') maybeStartTour();
